import math

def f(x, y):
    return x**2 * y + math.exp(x * y)

# exact f_y(1, 0) = x^2 + x*e^(xy) = 2
for h in [0.1, 0.001, 0.00001]:
    approx = (f(1, h) - f(1, -h)) / (2 * h)
    print("h =", h, "approx =", round(approx, 5))

